"use client";

// Lucide artwork is covered by components/icon/lucide.license.

/* oxlint-disable eslint/eqeqeq, eslint/no-eq-null -- The component tests `!= null` for the leading node and the actions; each test stays as written. */
/* oxlint-disable eslint/complexity -- Alert and the toast content keeps one branch per case. */
/* oxlint-disable shadcn/no-arbitrary-values -- The leading utility preserves the alert line height. */
/* oxlint-disable anti-slop/no-runtime-typeof -- The component wraps string children in a font-medium div. */

import { createIcon } from "@/components/icon";
import { Button } from "@/components/ui/button";
import type { ComponentType, ReactNode } from "react";

import type { ToastAction, ToastLevel, ToastVariant } from "./types";

/*
 * Alert joins class names with clsx, not tailwind-merge, so conflicting
 * utilities remain and stylesheet order decides which applies.
 */

type ClassValue =
  | Record<string, boolean | undefined>
  | false
  | string
  | undefined;

const classNames = (...values: ClassValue[]) =>
  values
    .flatMap((value) => {
      if (value === undefined || value === false) {
        return [];
      }

      if (typeof value === "string") {
        return [value];
      }

      return Object.entries(value).flatMap(([name, on]) =>
        on === true ? [name] : []
      );
    })
    .join(" ");

const DEFAULT_CLOSE_LABEL = "Close";

// The component also lists alert-root and box-shadow-lg, which
// have no CSS, so they are left out.
const SURFACE_CLASS_NAME =
  "inline-flex flex-col gap-2 rounded-xl px-3 py-2 text-base leading-[1.4] pointer-events-auto border";

const CONTENT_CLASS_NAME =
  "[pointer-events:all] min-w-0 max-w-full shadow-(--shadow-toast)";

const InfoIcon = createIcon({
  body: '<g fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M12 16v-4"></path><path d="M12 8h.01"></path></g>',
  canvas: { height: 16, viewBox: "0 0 24 24", width: 16 },
  name: "circle-info-16",
});

const SuccessIcon = createIcon({
  body: '<g fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="m16 9-5.5 5.5L8 12"></path></g>',
  canvas: { height: 16, viewBox: "0 0 24 24", width: 16 },
  name: "circle-check-16",
});

const AlertIcon = createIcon({
  body: '<g fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" x2="12" y1="8" y2="12"></line><line x1="12" x2="12.01" y1="16" y2="16"></line></g>',
  canvas: { height: 16, viewBox: "0 0 24 24", width: 16 },
  name: "circle-exclamation-mark-16",
});

const SuccessSolidIcon = createIcon({
  body: '<g fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="m16 9-5.5 5.5L8 12"></path></g>',
  canvas: { height: 20, viewBox: "0 0 24 24", width: 20 },
  name: "circle-check-20",
});

const CloseIcon = createIcon({
  body: '<g fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18"></path><path d="m6 6 12 12"></path></g>',
  canvas: { height: 16, viewBox: "0 0 24 24", width: 16 },
  name: "xmark-16",
});

export interface ToastAlertProps {
  actions?: ReactNode;
  actionsInline?: boolean;
  /** Renders role="alert" (default true); the toast content turns it off. */
  announce?: boolean;
  children?: ReactNode;
  className?: string;
  /** Label of the close button; the default is "Close". */
  closeLabel?: string;
  contentAlignment?: "center";
  fullWidth?: boolean;
  icon?: ComponentType<{ className?: string }>;
  leading?: ReactNode;
  level?: ToastLevel;
  onRemove?: () => void;
  richColors?: boolean;
  testId?: string;
  variant?: ToastVariant;
}

// Theme values of the Electron token layer. light-dark resolves each pair against the
// nearest theme scope at any depth.
const THEME_VARIABLES = [
  // --color-text-positive: --ck-palette-accent-green (green-500 / green-300).
  "[--toast-success:var(--color-status-success)]",
  // --color-text-alert: --ck-palette-label-warning (orange-500 / orange-300).
  "[--toast-warning:var(--color-status-warning)]",
  // --color-text-error: --ck-palette-label-error (red-500 / red-300).
  "[--toast-danger:var(--color-status-danger)]",
  // --color-fill-{success,warning,danger}-surface (-25 / -950 steps).
  "[--toast-success-surface:var(--color-status-success-surface)]",
  "[--toast-warning-surface:var(--color-status-warning-surface)]",
  "[--toast-danger-surface:var(--color-status-danger-surface)]",
  // --color-stroke-warning-outline / -danger-outline: --ck-palette-border-*.
  "[--toast-warning-outline:var(--color-status-warning)]",
  "[--toast-danger-outline:var(--color-status-danger)]",
  // --color-fill-success-solid and -danger-solid.
  "[--toast-success-solid:var(--color-status-success-solid)]",
  "[--toast-danger-solid:var(--color-status-danger-solid)]",
].join(" ");

/** The alert surface, leading icon slot, content, actions and close. */
export const ToastAlert = ({
  actions,
  actionsInline = false,
  announce = true,
  children,
  className,
  closeLabel = DEFAULT_CLOSE_LABEL,
  contentAlignment,
  fullWidth,
  icon: LeadingIcon,
  leading,
  level = "info",
  onRemove,
  richColors = false,
  testId,
  variant = "default",
}: ToastAlertProps) => {
  const isDefault = variant === "default";

  const infoSurface =
    isDefault && (level === "info" || (level === "success" && !richColors));

  const successSurface = isDefault && level === "success" && richColors;
  const successNeutral = variant === "successNeutral";
  const successSolid = variant === "successSolid";
  const dangerSolid = variant === "dangerSolid";
  const warningSurface = isDefault && level === "warning";
  const dangerSurface = isDefault && level === "danger";
  const defaultText = isDefault && (!richColors || level === "info");
  const successText = isDefault && richColors && level === "success";
  const warningText = isDefault && richColors && level === "warning";
  const dangerText = isDefault && richColors && level === "danger";
  const centered = contentAlignment === "center";

  const surfaceClassName = classNames(
    THEME_VARIABLES,
    SURFACE_CLASS_NAME,
    {
      "border-(--toast-danger-outline) bg-(--toast-danger-surface)":
        dangerSurface,
      "border-(--toast-success)/20 bg-(--toast-success-surface)":
        successSurface,
      "border-(--toast-warning-outline) bg-(--toast-warning-surface)":
        warningSurface,
      "border-border bg-panel-elevated-secondary": infoSurface,
      "border-transparent bg-(--toast-danger-solid) text-white": dangerSolid,
      "border-transparent bg-(--toast-success-solid) text-white": successSolid,
      "border-transparent bg-fill-primary-solid text-text-strong-solid":
        successNeutral,
      flex: fullWidth,
      "text-(--toast-danger)": dangerText,
      "text-(--toast-success)": successText,
      "text-(--toast-warning)": warningText,
      "text-text": defaultText,
    },
    className
  );

  const leadingSlot =
    leading != null || LeadingIcon ? (
      <div
        className={classNames(
          "flex size-6 shrink-0 grow-0 items-center justify-center",
          {
            "self-start": !centered,
            "text-text": isDefault && !richColors,
          }
        )}
      >
        {leading ??
          (LeadingIcon ? (
            <LeadingIcon className="size-(--icon-size,16px)" />
          ) : null)}
      </div>
    ) : null;

  return (
    <div
      className={surfaceClassName}
      data-testid={testId}
      role={announce ? "alert" : undefined}
    >
      <div
        className={classNames(
          "flex min-w-0",
          centered ? "items-center gap-3" : "items-start gap-1"
        )}
      >
        {leadingSlot}
        <div
          className={classNames(
            "flex min-w-0 flex-1 gap-3",
            centered ? "items-center" : "items-start"
          )}
        >
          <div className="min-w-0 flex-1 justify-center gap-2 break-words">
            {typeof children === "string" ? (
              <div className="font-medium">{children}</div>
            ) : (
              children
            )}
          </div>
          {actionsInline && actions != null ? (
            <div className="flex shrink-0 items-center gap-2">{actions}</div>
          ) : null}
        </div>
        {onRemove ? (
          <button
            aria-label={closeLabel}
            className={classNames(
              "flex size-6 shrink-0 grow-0 cursor-(--ck-action-cursor) items-center justify-center rounded-full hover:bg-fill-primary-transparent-hover/5",
              { "self-start": !centered }
            )}
            onClick={onRemove}
            type="button"
          >
            <CloseIcon aria-hidden={false} />
          </button>
        ) : null}
      </div>
      {!actionsInline && actions != null ? (
        <div className="flex items-center justify-end gap-2">{actions}</div>
      ) : null}
    </div>
  );
};

export interface ToastContentProps {
  actionPlacement?: "inline";
  closeLabel?: string;
  description?: ReactNode;
  leading?: ReactNode;
  level: ToastLevel;
  onClose?: () => void;
  primaryAction?: ToastAction;
  secondaryAction?: ToastAction;
  testId?: string;
  title?: ReactNode;
  variant?: ToastVariant;
}

const LEVEL_ICONS = {
  danger: AlertIcon,
  info: InfoIcon,
  success: SuccessIcon,
  warning: AlertIcon,
} as const;

const descriptionClassName = (variant: ToastVariant, level: ToastLevel) =>
  classNames("text-start", {
    "text-(--toast-danger)": variant === "default" && level === "danger",
    "text-(--toast-success)": variant === "default" && level === "success",
    "text-(--toast-warning)": variant === "default" && level === "warning",
    "text-sm font-normal": variant === "successSolid",
    "text-text-muted": variant === "default" && level === "info",
    "text-text-strong-solid": variant === "successNeutral",
    "text-white": variant === "dangerSolid",
  });

/** Toast content uses the Alert with the level icon, title, description and actions. */
export const ToastContent = ({
  actionPlacement,
  closeLabel,
  description,
  leading,
  level,
  onClose,
  primaryAction,
  secondaryAction,
  testId,
  title,
  variant = "default",
}: ToastContentProps) => {
  const compactActions =
    variant === "successNeutral" || variant === "successSolid";

  let primaryColor: "primary" | "successOutline" | "tinted" = "primary";

  if (variant === "successSolid") {
    primaryColor = "successOutline";
  } else if (variant === "successNeutral") {
    primaryColor = "tinted";
  }

  const inline = actionPlacement === "inline";

  const LevelIcon =
    variant === "successSolid" ? SuccessSolidIcon : LEVEL_ICONS[level];

  const actions =
    primaryAction != null || secondaryAction != null ? (
      <>
        {secondaryAction == null ? null : (
          <Button
            color={variant === "successSolid" ? "successOutline" : "secondary"}
            {...secondaryAction.dataAttributes}
            loading={secondaryAction.loading}
            onClick={() => {
              secondaryAction.onClick();
            }}
            size={compactActions ? "actionSm" : "compact"}
          >
            {secondaryAction.label}
          </Button>
        )}
        {primaryAction == null ? null : (
          <Button
            color={primaryColor}
            {...primaryAction.dataAttributes}
            loading={primaryAction.loading}
            onClick={() => {
              primaryAction.onClick();
            }}
            size={compactActions ? "actionSm" : "compact"}
          >
            {primaryAction.label}
          </Button>
        )}
      </>
    ) : undefined;

  return (
    <ToastAlert
      actions={actions}
      actionsInline={inline || description == null}
      announce={false}
      className={classNames(
        CONTENT_CLASS_NAME,
        {
          "[&_a]:text-inherit! [&_a]:underline!": variant === "successSolid",
        },
        "leading-normal",
        { "w-max": inline }
      )}
      closeLabel={closeLabel}
      contentAlignment={inline ? "center" : undefined}
      fullWidth
      leading={
        leading === undefined ? <LevelIcon aria-hidden={false} /> : leading
      }
      level={level}
      onRemove={onClose}
      richColors
      testId={testId}
      variant={variant}
    >
      <div className="min-w-0">
        <div
          className={classNames(
            "flex min-h-6 items-center text-start whitespace-pre-wrap",
            variant === "successSolid"
              ? "text-base font-semibold"
              : "font-medium"
          )}
        >
          {title}
        </div>
        {description == null ? null : (
          <div className={descriptionClassName(variant, level)}>
            {description}
          </div>
        )}
      </div>
    </ToastAlert>
  );
};

"use client";

/* oxlint-disable eslint/eqeqeq, eslint/no-eq-null -- The component tests `!= null` for ids, actions and the content option; each test stays as written. */
/* oxlint-disable typescript/consistent-return, typescript/strict-void-return, typescript/promise-function-async -- Ref callbacks and layout effects return a cleanup only when they registered something, and the toast slot returns the caller's node. */
/* oxlint-disable eslint/complexity -- The toast factory keeps one branch per case. */
/* oxlint-disable anti-slop/no-runtime-typeof, anti-slop/no-unknown-parameters -- Refs are callbacks or objects and the analytics payload is an opaque option. */
/* oxlint-disable anti-slop/require-safety-comment-for-type-assertion, typescript/no-unsafe-type-assertion -- closest returns the toast li that Sonner renders and the window/node casts follow floating-ui. */

import { useLayoutEffect, useRef, useSyncExternalStore } from "react";
import type { ComponentProps, ReactNode, Ref } from "react";

import { ToastContent } from "./alert";
import { sonnerToast } from "./sonner";
import type { ToastPosition } from "./sonner";
import type { ToastAction, ToastLevel, ToastVariant } from "./types";

import styles from "./toast.module.css";

/* Toast management and positioning over registered content anchors. */

/** Seconds a toast stays when `duration` is not given. */
const DEFAULT_TOAST_DURATION_SECONDS = 4.5;
const MS_PER_SECOND = 1000;
const REMOVE_RECYCLE_FRAMES = 2;
const SPACING_ROWS = 4;
const OVERFLOW_PATTERN = /auto|scroll|overlay|hidden|clip/u;

export type ToastManagerPosition = "top-center-content" | ToastPosition;

export interface ToastRenderContext {
  close: () => void;
  level: ToastLevel;
}

export interface ToastOptions {
  actionPlacement?: "inline";
  /** Custom toasts: renders this instead of the Alert. */
  content?: (context: ToastRenderContext) => ReactNode;
  description?: ReactNode;
  /** Seconds; 0 keeps the toast until it is closed. */
  duration?: number;
  errorAnalytics?: unknown;
  /** false hides the close button and makes the toast non-dismissible. */
  hasCloseButton?: boolean;
  /** An existing id closes the earlier toast with that id. */
  id?: string;
  leading?: ReactNode;
  /** Custom toasts: the level passed to `content` (default info). */
  level?: ToastLevel;
  onRemove?: () => void;
  onUserDismiss?: () => void;
  position?: ToastManagerPosition;
  primaryAction?: ToastAction;
  secondaryAction?: ToastAction;
  testId?: string;
  variant?: ToastVariant;
}

export interface ToastHandle {
  close: () => void;
}

export interface ToastManager {
  closeAll: () => void;
  custom: (options: ToastOptions) => ToastHandle;
  danger: (title: ReactNode, options?: ToastOptions) => ToastHandle;
  info: (title: ReactNode, options?: ToastOptions) => ToastHandle;
  registerViewport: () => () => void;
  success: (title: ReactNode, options?: ToastOptions) => ToastHandle;
  warning: (title: ReactNode, options?: ToastOptions) => ToastHandle;
}

/* Merges refs; callback refs may return a cleanup function. */
export const mergeRefs =
  <T,>(...refs: (Ref<T> | undefined)[]) =>
  (value: T | null) => {
    if (value === null) {
      for (const ref of refs) {
        if (typeof ref === "function") {
          ref(null);
        } else if (ref) {
          ref.current = null;
        }
      }

      return;
    }

    const cleanups: (() => void)[] = [];

    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(value);
        cleanups.push(
          typeof cleanup === "function"
            ? cleanup
            : () => {
                ref(null);
              }
        );
      } else if (ref) {
        ref.current = value;
        cleanups.push(() => {
          ref.current = null;
        });
      }
    }

    if (cleanups.length > 0) {
      return () => {
        for (const cleanup of cleanups) {
          cleanup();
        }
      };
    }
  };

/* The registry of content anchors; the last one wins. */
let anchors: readonly HTMLElement[] = [];
const anchorListeners = new Set<() => void>();

const setAnchors = (
  update: (current: readonly HTMLElement[]) => HTMLElement[]
) => {
  anchors = update(anchors);

  for (const listener of anchorListeners) {
    listener();
  }
};

const subscribeAnchors = (listener: () => void) => {
  anchorListeners.add(listener);

  return () => {
    anchorListeners.delete(listener);
  };
};

const readAnchors = () => anchors;
const readNoAnchors = (): readonly HTMLElement[] => [];

const registerAnchor = (element: HTMLDivElement | null) => {
  if (element === null) {
    return;
  }

  setAnchors((current) => [...current, element]);

  return () => {
    setAnchors((current) => current.filter((entry) => entry !== element));
  };
};

/** A div that registers itself as the column that `top-center-content` toasts centre over. */
export const ToastContentAnchor = ({
  ref,
  ...props
}: ComponentProps<"div">) => (
  <div {...props} ref={mergeRefs(ref, registerAnchor)} />
);

type ScrollTarget = Element | VisualViewport | Window;

const LAST_TRAVERSABLE = /^(?:html|body|#document)$/u;

const nodeName = (node: Node) => (node.nodeName || "").toLowerCase();

const viewOf = (node: Node | Window): Window =>
  (node as Node).ownerDocument?.defaultView ?? window;

/* An element that can scroll or clip its content. */
const isOverflowElement = (element: Element) => {
  const { overflow, overflowX, overflowY, display } =
    viewOf(element).getComputedStyle(element);

  return (
    OVERFLOW_PATTERN.test(`${overflow}${overflowY}${overflowX}`) &&
    display !== "inline" &&
    display !== "contents"
  );
};

/* The parent node, through slots and shadow roots. */
const parentNodeOf = (node: Node): Node => {
  if (nodeName(node) === "html") {
    return node;
  }

  const slotted = (node as Element).assignedSlot;
  const host = node instanceof ShadowRoot ? node.host : null;

  const parent =
    slotted ?? node.parentNode ?? host ?? viewOf(node).document.documentElement;

  return parent instanceof ShadowRoot ? parent.host : parent;
};

/* The nearest scrolling ancestor, or the body. */
const nearestOverflowAncestor = (node: Node): HTMLElement => {
  const parent = parentNodeOf(node);

  if (LAST_TRAVERSABLE.test(nodeName(parent))) {
    return (node.ownerDocument ?? (node as Document)).body;
  }

  if (parent instanceof HTMLElement && isOverflowElement(parent)) {
    return parent;
  }

  return nearestOverflowAncestor(parent);
};

/* The frame element of an embedded window. */
const frameOf = (view: Window) =>
  view.parent !== null && Object.getPrototypeOf(view.parent) !== null
    ? view.frameElement
    : null;

/* The scrolling ancestors, then the window, its visual viewport and the frames. */
const overflowAncestors = (
  node: Element,
  list: ScrollTarget[] = [],
  traverseIframes = true
): ScrollTarget[] => {
  const nearest = nearestOverflowAncestor(node);
  const isBody = nearest === node.ownerDocument?.body;
  const view = viewOf(nearest);

  if (isBody) {
    const frame = frameOf(view);

    return [
      ...list,
      view,
      ...(view.visualViewport ? [view.visualViewport] : []),
      ...(isOverflowElement(nearest) ? [nearest] : []),
      ...(frame !== null && traverseIframes ? overflowAncestors(frame) : []),
    ];
  }

  return [...list, nearest, ...overflowAncestors(nearest, [], traverseIframes)];
};

const sameRect = (left: DOMRect, right: DOMRect) =>
  left.x === right.x &&
  left.y === right.y &&
  left.width === right.width &&
  left.height === right.height;

/* Calls onMove when the element moves in the layout. */
const observeMove = (
  element: Element,
  onMove: () => void,
  skipOnResize: boolean
) => {
  let observer: IntersectionObserver | null = null;
  let timeoutId: ReturnType<typeof setTimeout> | undefined;
  const root = element.ownerDocument.documentElement;

  const cleanup = () => {
    clearTimeout(timeoutId);
    observer?.disconnect();
    observer = null;
  };

  const refresh = (skip = false, threshold = 1) => {
    cleanup();
    const rect = element.getBoundingClientRect();
    const { left, top, width, height } = rect;

    if (!skip) {
      onMove();
    }

    if (!width || !height) {
      return;
    }

    const insetTop = Math.floor(top);
    const insetRight = Math.floor(root.clientWidth - (left + width));
    const insetBottom = Math.floor(root.clientHeight - (top + height));
    const insetLeft = Math.floor(left);

    const options = {
      rootMargin: `${-insetTop}px ${-insetRight}px ${-insetBottom}px ${-insetLeft}px`,
      threshold: Math.max(0, Math.min(1, threshold)) || 1,
    };

    let firstUpdate = true;

    const handle = (entries: IntersectionObserverEntry[]) => {
      const ratio = entries[0]?.intersectionRatio ?? 0;

      if (!sameRect(rect, element.getBoundingClientRect())) {
        refresh();

        return;
      }

      if (ratio !== threshold) {
        if (!firstUpdate) {
          refresh();

          return;
        }

        if (ratio) {
          refresh(false, ratio);
        } else {
          timeoutId = setTimeout(() => {
            refresh(false, 1e-7);
          }, 1000);
        }
      }

      firstUpdate = false;
    };

    try {
      observer = new IntersectionObserver(handle, {
        ...options,
        root: element.ownerDocument,
      });
    } catch {
      observer = new IntersectionObserver(handle, options);
    }

    observer.observe(element);
  };

  const onResize = () => {
    refresh(skipOnResize);
  };

  const view = element.ownerDocument.defaultView ?? window;
  view.addEventListener("resize", onResize);
  refresh(true);

  return () => {
    view.removeEventListener("resize", onResize);
    cleanup();
  };
};

/* Floating-ui autoUpdate for a reference element (no floating element). */
const autoUpdate = (reference: Element, update: () => void) => {
  const targets = overflowAncestors(reference);

  for (const target of targets) {
    target.addEventListener("scroll", update);
    target.addEventListener("resize", update);
  }

  const stopMove =
    typeof IntersectionObserver === "function"
      ? observeMove(reference, update, true)
      : null;

  const resizeObserver =
    typeof ResizeObserver === "function"
      ? new ResizeObserver(() => {
          update();
        })
      : null;

  resizeObserver?.observe(reference);
  update();

  return () => {
    for (const target of targets) {
      target.removeEventListener("scroll", update);
      target.removeEventListener("resize", update);
    }

    stopMove?.();
    resizeObserver?.disconnect();
  };
};

/** Centres the toast over the last registered content anchor. */
const ToastContentCentered = ({ children }: { children: ReactNode }) => {
  const registered = useSyncExternalStore(
    subscribeAnchors,
    readAnchors,
    readNoAnchors
  );

  const anchor = registered.at(-1);
  const ref = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const toast = ref.current?.closest<HTMLElement>("[data-sonner-toast]");

    if (!toast || !anchor) {
      return;
    }

    const stop = autoUpdate(anchor, () => {
      const { left, width } = anchor.getBoundingClientRect();
      toast.style.setProperty(
        "--toast-body-offset-x",
        `${left + width / 2 - window.innerWidth / 2}px`
      );
      toast.style.setProperty(
        "--toast-body-max-width",
        `calc(${width}px - var(--spacing) * ${SPACING_ROWS})`
      );
    });

    return () => {
      stop();
      toast.style.removeProperty("--toast-body-offset-x");
      toast.style.removeProperty("--toast-body-max-width");
    };
  }, [anchor]);

  return (
    <div className="contents" ref={ref}>
      {children}
    </div>
  );
};

/** Renders the toast content and reports mount and unmount to the manager. */
const ManagedToast = ({
  content,
  isRemoved,
  onMount,
}: {
  content: ReactNode;
  isRemoved: () => boolean;
  onMount: () => () => void;
}) => {
  useLayoutEffect(onMount, [onMount]);

  return isRemoved() ? null : content;
};

let toastSequence = 1;

interface ToastManagerConfig {
  /** Called for every danger toast with its `errorAnalytics` option. */
  onDanger?: (analytics: unknown) => void;
  /** Id prefix and the Toaster id the toasts belong to. */
  scopeId: string;
  /** Close button label passed to the Alert; the default is "Close". */
  closeLabel?: string;
}

/** The toast manager of one provider. */
export const createToastManager = ({
  closeLabel,
  onDanger,
  scopeId,
}: ToastManagerConfig): ToastManager => {
  let viewportRegistered = false;
  const pending = new Map<string, () => void>();
  const closers = new Map<string, () => void>();
  const sequences = new Map<string, number>();
  const idsByCustomId = new Map<string, string>();
  const recycledIds: string[] = [];

  const show = (
    title: ReactNode,
    options: ToastOptions | undefined,
    level: ToastLevel
  ): ToastHandle => {
    if (level === "danger") {
      try {
        onDanger?.(options?.errorAnalytics);
      } catch {
        // The analytics callback must not stop the toast.
      }
    }

    const sequence = toastSequence;
    toastSequence += 1;
    const id = recycledIds.pop() ?? `${scopeId}-toast-${sequence}`;
    sequences.set(id, sequence);
    let shownInSonner = false;
    let removed = false;
    let cleanedUp = false;
    let closeRequested = false;
    let mounted = false;
    let recycling = false;

    const recycle = () => {
      if (!cleanedUp || mounted || recycling) {
        return;
      }

      recycling = true;
      let frames = REMOVE_RECYCLE_FRAMES;

      const step = () => {
        frames -= 1;

        if (frames > 0) {
          requestAnimationFrame(step);

          return;
        }

        if (mounted) {
          recycling = false;
        } else {
          recycledIds.push(id);
        }
      };

      requestAnimationFrame(step);
    };

    const finish = () => {
      if (removed) {
        return;
      }

      removed = true;

      if (closers.size === 1) {
        const active = document.activeElement;

        if (
          active instanceof HTMLElement &&
          active.closest("[data-sonner-toaster]") !== null
        ) {
          active.blur();
        }
      }

      pending.delete(id);
      closers.delete(id);
      sequences.delete(id);

      if (options?.id != null && idsByCustomId.get(options.id) === id) {
        idsByCustomId.delete(options.id);
      }

      try {
        options?.onRemove?.();
      } catch {
        // A failing onRemove must not stop the removal.
      }
    };

    const cleanup = () => {
      finish();

      if (!cleanedUp) {
        cleanedUp = true;
        recycle();
      }
    };

    const close = () => {
      if (removed || sequences.get(id) !== sequence) {
        return;
      }

      closeRequested = true;

      if (shownInSonner) {
        sonnerToast.dismiss(id);
        finish();
      } else {
        cleanup();
      }
    };

    const previous =
      options?.id == null ? undefined : idsByCustomId.get(options.id);

    if (previous != null) {
      closers.get(previous)?.();
    }

    if (options?.id != null) {
      idsByCustomId.set(options.id, id);
    }

    closers.set(id, close);

    const onUserDismiss = () => {
      if (
        !removed &&
        !closeRequested &&
        options != null &&
        "content" in options
      ) {
        try {
          options.onUserDismiss?.();
        } catch {
          // A failing onUserDismiss must not stop the dismissal.
        }
      }

      cleanup();
    };

    const onMount = () => {
      mounted = true;
      const seconds = options?.duration ?? DEFAULT_TOAST_DURATION_SECONDS;

      const timer =
        level === "success" &&
        options?.duration !== 0 &&
        Number.isFinite(seconds) &&
        options?.primaryAction == null &&
        options?.secondaryAction == null &&
        !(options != null && "content" in options)
          ? setTimeout(close, seconds * MS_PER_SECOND)
          : undefined;

      return () => {
        clearTimeout(timer);
        mounted = false;
        queueMicrotask(() => {
          if (!mounted) {
            cleanup();
            recycle();
          }
        });
      };
    };

    const body =
      options != null && "content" in options && options.content ? (
        <div className="max-w-full min-w-0" data-testid={options.testId}>
          {options.content({ close, level })}
        </div>
      ) : (
        <ToastContent
          actionPlacement={options?.actionPlacement}
          closeLabel={closeLabel}
          description={options?.description}
          leading={options?.leading}
          level={level}
          onClose={options?.hasCloseButton === false ? undefined : close}
          primaryAction={options?.primaryAction}
          secondaryAction={options?.secondaryAction}
          testId={options?.testId}
          title={title}
          variant={options?.variant}
        />
      );

    const position = options?.position ?? "top-center";
    const centered = position === "top-center-content";

    const showInSonner = () => {
      shownInSonner = true;
      sonnerToast.custom(
        () => (
          <ManagedToast
            content={
              centered ? (
                <ToastContentCentered>{body}</ToastContentCentered>
              ) : (
                body
              )
            }
            isRemoved={() => removed}
            onMount={onMount}
          />
        ),
        {
          className: centered ? styles.contentCentered : undefined,
          dismissible: options?.hasCloseButton ?? true,
          duration:
            options?.duration === 0
              ? Number.POSITIVE_INFINITY
              : (options?.duration ?? DEFAULT_TOAST_DURATION_SECONDS) *
                MS_PER_SECOND,
          id,
          onAutoClose: cleanup,
          onDismiss: onUserDismiss,
          position: centered ? "top-center" : position,
          toasterId: scopeId,
          unstyled: true,
        }
      );
    };

    if (!removed) {
      pending.set(id, showInSonner);

      if (viewportRegistered) {
        showInSonner();
      }
    }

    return { close };
  };

  return {
    closeAll() {
      // CloseAll copies the closers first: an onRemove that creates
      // another toast must not get that new toast closed by this call.
      const snapshot = [...closers.values()];

      for (const close of snapshot) {
        close();
      }
    },
    custom(options) {
      return show(null, options, options.level ?? "info");
    },
    danger(title, options) {
      return show(title, options, "danger");
    },
    info(title, options) {
      return show(title, options, "info");
    },
    registerViewport() {
      viewportRegistered = true;

      for (const showPending of pending.values()) {
        showPending();
      }

      return () => {
        viewportRegistered = false;
      };
    },
    success(title, options) {
      return show(title, options, "success");
    },
    warning(title, options) {
      return show(title, options, "warning");
    },
  };
};

"use client";

/* oxlint-disable typescript/strict-boolean-expressions, typescript/prefer-nullish-coalescing -- Sonner branches on JavaScript truthiness (`toast.duration || duration || 4000` skips 0, an id of 0 or "" counts as missing); each condition stays as written. */
/* oxlint-disable anti-slop/no-runtime-typeof, anti-slop/no-unknown-parameters, anti-slop/no-unknown-returns, anti-slop/no-known-value-widening, anti-slop/no-unsafe-dictionary-type -- The store takes callers values (React nodes, functions, objects, promise results and thrown errors) and branches on their type. */
/* oxlint-disable typescript/no-unsafe-type-assertion, anti-slop/require-safety-comment-for-type-assertion, anti-slop/no-chained-type-assertions -- Toast custom properties, event targets and promise results are asserted where the component reads them untyped. */
/* oxlint-disable eslint/complexity -- The toast, its pointer handlers and the toaster keep one branch per case. */
/* oxlint-disable promise/avoid-new, promise/always-return, promise/valid-params, promise/prefer-await-to-callbacks, promise/no-multiple-resolved, eslint/no-unused-expressions -- toast.promise keeps the promise chain and its unwrap. */
/* oxlint-disable jsx-a11y/no-noninteractive-tabindex, jsx-a11y/no-noninteractive-element-interactions -- The toast li is focusable (tabIndex 0) and handles pointer swipes. */
/* oxlint-disable typescript/consistent-return, typescript/switch-exhaustiveness-check, typescript/promise-function-async, typescript/prefer-promise-reject-errors -- Effects return a cleanup only when they subscribed, the handler answers null for the types without an icon, resolveContent returns the caller's React node and unwrap rejects with the original reason. */
/* oxlint-disable shadcn/no-inline-styles -- Sonner sets its layout through style custom properties and forwards the style props of the caller. */
/* oxlint-disable unicorn/no-array-reduce -- The component sums the heights before a toast with reduce. */
/* oxlint-disable react/exhaustive-effect-dependencies -- The effects list these dependencies (content props re-measure the toast; the toast object re-arms the timer). */
/* oxlint-disable unicorn/no-instanceof-builtins -- toast.promise tests `instanceof Function` and `instanceof Error`. */

