      fillRule="evenodd"
    />
  </svg>
);

const CloseGlyph = (
  <svg
    fill="none"
    height="12"
    stroke="currentColor"
    strokeLinecap="round"
    strokeLinejoin="round"
    strokeWidth="1.5"
    viewBox="0 0 24 24"
    width="12"
    xmlns="http://www.w3.org/2000/svg"
  >
    <line x1="18" x2="6" y1="6" y2="18" />
    <line x1="6" x2="18" y1="6" y2="18" />
  </svg>
);

const iconForType = (type: ToastType | undefined) => {
  switch (type) {
    case "success": {
      return SuccessIcon;
    }

    case "info": {
      return InfoIcon;
    }

    case "warning": {
      return WarningIcon;
    }

    case "error": {
      return ErrorIcon;
    }

    default: {
      return null;
    }
  }
};

const Loader = ({
  className,
  visible,
}: {
  className?: string;
  visible: boolean;
}) => (
  <div className={cn(styles.loadingWrapper, className)} data-visible={visible}>
    <div className={styles.spinner}>
      {LOADER_BARS.map((bar) => (
        <div className={styles.loadingBar} key={`spinner-bar-${bar}`} />
      ))}
    </div>
  </div>
);

export type ToastIcons = Partial<
  Record<
    "close" | "error" | "info" | "loading" | "success" | "warning",
    ReactNode
  >
>;

interface SonnerToastProps {
  actionButtonStyle?: CSSProperties;
  cancelButtonStyle?: CSSProperties;
  className?: string;
  classNames?: ToastClassNames;
  closeButton?: boolean;
  closeButtonAriaLabel?: string;
  defaultRichColors?: boolean;
  descriptionClassName?: string;
  duration?: number;
  expandByDefault?: boolean;
  expanded: boolean;
  gap: number;
  heights: ToastHeight[];
  icons?: ToastIcons;
  index: number;
  interacting: boolean;
  invert?: boolean;
  position: ToastPosition;
  removeToast: (toast: ToastData) => void;
  setHeights: (update: (heights: ToastHeight[]) => ToastHeight[]) => void;
  style?: CSSProperties;
  swipeDirections?: SwipeDirection[];
  toast: ToastData;
  toasts: ToastData[];
  unstyled?: boolean;
  visibleToasts: number;
}

type DragAxis = "x" | "y";

/* The damping applied to a drag against an allowed direction. */
const damping = (distance: number) =>
  1 / (DAMPING_BASE + Math.abs(distance) / DAMPING_DISTANCE);

type SwipeOutDirection = "down" | "left" | "right" | "up";

const readSwipeAmount = (element: HTMLElement | null, name: string) =>
  Number(element?.style.getPropertyValue(name).replace("px", "") || 0);

const toastIconSlot = (
  toast: ToastData,
  icons: ToastIcons | undefined,
  classNames: ToastClassNames | undefined
) => {
  const type = toast.type ?? undefined;

  const typeIcon =
    type === undefined ? undefined : icons?.[type as keyof ToastIcons];

  const showsSlot =
    (type || toast.icon || toast.promise) &&
    toast.icon !== null &&
    (typeIcon !== null || toast.icon);

  if (!showsSlot) {
    return null;
  }

  const loaderClassName = cn(classNames?.loader, toast.classNames?.loader);

  const loader = icons?.loading ? (
    <div
      className={cn(loaderClassName, styles.loader)}
      data-visible={type === "loading"}
    >
      {icons.loading}
    </div>
  ) : (
    <Loader className={loaderClassName} visible={type === "loading"} />
  );

  const fallbackIcon = toast.icon || typeIcon || iconForType(type);
  const showsLoader = toast.promise || (type === "loading" && !toast.icon);

  return (
    <div className={cn(classNames?.icon, toast.classNames?.icon)} data-icon="">
      {showsLoader ? toast.icon || loader : null}
      {type === "loading" ? null : fallbackIcon}
    </div>
  );
};

const SonnerToast = (props: SonnerToastProps) => {
  const {
    toast,
    unstyled,
    interacting,
    setHeights,
    visibleToasts,
    heights,
    index,
    toasts,
    expanded,
    removeToast,
    defaultRichColors,
    closeButton: closeButtonDefault,
    style,
    cancelButtonStyle,
    actionButtonStyle,
    className,
    descriptionClassName,
    duration,
    position,
    gap,
    expandByDefault,
    classNames,
    icons,
    closeButtonAriaLabel = DEFAULT_CLOSE_LABEL,
    invert,
    swipeDirections,
  } = props;

  const [swipeDirection, setSwipeDirection] = useState<DragAxis | null>(null);

  const [swipeOutDirection, setSwipeOutDirection] =
    useState<SwipeOutDirection | null>(null);

  const [mounted, setMounted] = useState(false);
  const [removed, setRemoved] = useState(false);
  const [swiping, setSwiping] = useState(false);
  const [swipeOut, setSwipeOut] = useState(false);
  const [isSwiped, setIsSwiped] = useState(false);
  const [offsetBeforeRemove, setOffsetBeforeRemove] = useState(0);
  const [initialHeight, setInitialHeight] = useState(0);

  const remainingTime = useRef(
    toast.duration || duration || FALLBACK_DURATION_MS
  );

  const dragStartTime = useRef<Date | null>(null);
  const toastRef = useRef<HTMLLIElement | null>(null);
  const isFront = index === 0;
  const isVisible = index + 1 <= visibleToasts;
  const toastType = toast.type;
  const dismissible = toast.dismissible !== false;

  const heightIndex = useMemo(
    () => heights.findIndex((height) => height.toastId === toast.id) || 0,
    [heights, toast.id]
  );

  const showsCloseButton = useMemo(
    () => toast.closeButton ?? closeButtonDefault,
    [toast.closeButton, closeButtonDefault]
  );

  const toastDuration = useMemo(
    () => toast.duration || duration || FALLBACK_DURATION_MS,
    [toast.duration, duration]
  );

  const closeTimerStartTime = useRef(0);
  const offset = useRef(0);
  const lastCloseTimerStartTime = useRef(0);
  const pointerStart = useRef<{ x: number; y: number } | null>(null);
  const [yPosition, xPosition] = position.split("-");

  const heightsBefore = useMemo(
    () =>
      heights.reduce(
        (total, height, heightsIndex) =>
          heightsIndex >= heightIndex ? total : total + height.height,
        0
      ),
    [heights, heightIndex]
  );

  const documentHidden = useDocumentHidden();
  const inverted = toast.invert || invert;
  const isLoading = toastType === "loading";

  const offsetValue = heightIndex * gap + heightsBefore;

  useLayoutEffect(() => {
    offset.current = offsetValue;
  }, [offsetValue]);

  useEffect(() => {
    remainingTime.current = toastDuration;
  }, [toastDuration]);

  useEffect(() => {
    // oxlint-disable-next-line react/set-state-in-effect -- The mounted flag starts the enter transition after the first paint.
    setMounted(true);
  }, []);

  useEffect(() => {
    const element = toastRef.current;

    if (!element) {
      return;
    }

    const { height } = element.getBoundingClientRect();
    setInitialHeight(height);
    setHeights((current) => [
      { height, position: toast.position, toastId: toast.id },
      ...current,
    ]);

    return () => {
      setHeights((current) =>
        current.filter((entry) => entry.toastId !== toast.id)
      );
    };
  }, [setHeights, toast.id, toast.position]);

  useLayoutEffect(() => {
    if (!mounted) {
      return;
    }

    const element = toastRef.current;

    if (!element) {
      return;
    }

    const previousHeight = element.style.height;
    element.style.height = "auto";
    const { height } = element.getBoundingClientRect();
    element.style.height = previousHeight;
    setInitialHeight(height);
    setHeights((current) =>
      current.some((entry) => entry.toastId === toast.id)
        ? current.map((entry) =>
            entry.toastId === toast.id ? { ...entry, height } : entry
          )
        : [{ height, position: toast.position, toastId: toast.id }, ...current]
    );
  }, [
    mounted,
    toast.title,
    toast.description,
    setHeights,
    toast.id,
    toast.jsx,
    toast.action,
    toast.cancel,
    toast.position,
  ]);

  const deleteToast = useCallback(() => {
    setRemoved(true);
    setOffsetBeforeRemove(offset.current);
    setHeights((current) =>
      current.filter((entry) => entry.toastId !== toast.id)
    );
    setTimeout(() => {
      removeToast(toast);
    }, REMOVAL_DELAY_MS);
  }, [toast, removeToast, setHeights]);

  useEffect(() => {
    if (
      (toast.promise && toastType === "loading") ||
      toast.duration === Number.POSITIVE_INFINITY ||
      toast.type === "loading"
    ) {
      return;
    }

    let timeoutId: ReturnType<typeof setTimeout> | undefined;

    if (expanded || interacting || documentHidden) {
      // Pause: subtract the time that ran since the timer started.
      if (lastCloseTimerStartTime.current < closeTimerStartTime.current) {
        const elapsed = Date.now() - closeTimerStartTime.current;
        remainingTime.current -= elapsed;
      }

      lastCloseTimerStartTime.current = Date.now();
    } else if (remainingTime.current !== Number.POSITIVE_INFINITY) {
      closeTimerStartTime.current = Date.now();
      timeoutId = setTimeout(() => {
        toast.onAutoClose?.(toast);
        deleteToast();
      }, remainingTime.current);
    }

    return () => {
      clearTimeout(timeoutId);
    };
  }, [expanded, interacting, toast, toastType, documentHidden, deleteToast]);

  useEffect(() => {
    if (toast.delete) {
      // oxlint-disable-next-line react/set-state-in-effect -- The delete flag from toast.dismiss starts the removal.
      deleteToast();
      toast.onDismiss?.(toast);
    }
  }, [deleteToast, toast.delete, toast]);

  const handlePointerDown = (event: ReactPointerEvent<HTMLLIElement>) => {
    if (event.button === 2 || isLoading || !dismissible) {
      return;
    }

    dragStartTime.current = new Date();
    setOffsetBeforeRemove(offset.current);
    const target = event.target as HTMLElement;
    target.setPointerCapture(event.pointerId);

    if (target.tagName !== "BUTTON") {
      setSwiping(true);
      pointerStart.current = { x: event.clientX, y: event.clientY };
    }
  };

  const handlePointerUp = () => {
    if (swipeOut || !dismissible) {
      return;
    }

    pointerStart.current = null;
    const swipeAmountX = readSwipeAmount(toastRef.current, "--swipe-amount-x");
    const swipeAmountY = readSwipeAmount(toastRef.current, "--swipe-amount-y");

    const elapsed =
      Date.now() - (dragStartTime.current?.getTime() ?? Number.NaN);

    const swipeAmount = swipeDirection === "x" ? swipeAmountX : swipeAmountY;
    const velocity = Math.abs(swipeAmount) / elapsed;

    if (Math.abs(swipeAmount) >= SWIPE_THRESHOLD || velocity > SWIPE_VELOCITY) {
      setOffsetBeforeRemove(offset.current);
      toast.onDismiss?.(toast);

      if (swipeDirection === "x") {
        setSwipeOutDirection(swipeAmountX > 0 ? "right" : "left");
      } else {
        setSwipeOutDirection(swipeAmountY > 0 ? "down" : "up");
      }

      deleteToast();
      setSwipeOut(true);
    } else {
      toastRef.current?.style.setProperty("--swipe-amount-x", "0px");
      toastRef.current?.style.setProperty("--swipe-amount-y", "0px");
      setIsSwiped(false);
      setSwiping(false);
      setSwipeDirection(null);
    }
  };

  const handlePointerMove = (event: ReactPointerEvent<HTMLLIElement>) => {
    if (
      !pointerStart.current ||
      !dismissible ||
      (window.getSelection()?.toString().length ?? 0) > 0
    ) {
      return;
    }

    const deltaY = event.clientY - pointerStart.current.y;
    const deltaX = event.clientX - pointerStart.current.x;
    const directions = swipeDirections ?? swipeDirectionsFor(position);

    if (
      !swipeDirection &&
      (Math.abs(deltaX) > DRAG_LOCK_DISTANCE ||
        Math.abs(deltaY) > DRAG_LOCK_DISTANCE)
    ) {
      setSwipeDirection(Math.abs(deltaX) > Math.abs(deltaY) ? "x" : "y");
    }

    const amount = { x: 0, y: 0 };

    if (swipeDirection === "y") {
      if (directions.includes("top") || directions.includes("bottom")) {
        if (
          (directions.includes("top") && deltaY < 0) ||
          (directions.includes("bottom") && deltaY > 0)
        ) {
          amount.y = deltaY;
        } else {
          const damped = deltaY * damping(deltaY);
          amount.y = Math.abs(damped) < Math.abs(deltaY) ? damped : deltaY;
        }
      }
    } else if (
      swipeDirection === "x" &&
      (directions.includes("left") || directions.includes("right"))
    ) {
      if (
        (directions.includes("left") && deltaX < 0) ||
        (directions.includes("right") && deltaX > 0)
      ) {
        amount.x = deltaX;
      } else {
        const damped = deltaX * damping(deltaX);
        amount.x = Math.abs(damped) < Math.abs(deltaX) ? damped : deltaX;
      }
    }

    if (Math.abs(amount.x) > 0 || Math.abs(amount.y) > 0) {
      setIsSwiped(true);
    }

    toastRef.current?.style.setProperty("--swipe-amount-x", `${amount.x}px`);
    toastRef.current?.style.setProperty("--swipe-amount-y", `${amount.y}px`);
  };

  const liStyle = {
    "--index": index,
    "--initial-height": expandByDefault ? "auto" : `${initialHeight}px`,
    "--offset": `${removed ? offsetBeforeRemove : offsetValue}px`,
    "--toasts-before": index,
    "--z-index": toasts.length - index,
    ...style,
    ...toast.style,
  } as CSSProperties;

  const typeClassName = toastType
    ? classNames?.[toastType as keyof ToastClassNames]
    : undefined;

  const toastTypeClassName = toastType
    ? toast.classNames?.[toastType as keyof ToastClassNames]
    : undefined;

  const cancelButton = (() => {
    if (isValidElement(toast.cancel)) {
      return toast.cancel;
    }

    const { cancel } = toast;

    if (!cancel || !isButtonSpec(cancel)) {
      return null;
    }

    return (
      <button
        className={cn(classNames?.cancelButton, toast.classNames?.cancelButton)}
        data-button
        data-cancel
        onClick={(event) => {
          if (dismissible) {
            cancel.onClick?.(event);
            deleteToast();
          }
        }}
        style={toast.cancelButtonStyle || cancelButtonStyle}
        type="button"
      >
        {cancel.label}
      </button>
    );
  })();

  const actionButton = (() => {
    if (isValidElement(toast.action)) {
      return toast.action;
    }

    const { action } = toast;

    if (!action || !isButtonSpec(action)) {
      return null;
    }

    return (
      <button
        className={cn(classNames?.actionButton, toast.classNames?.actionButton)}
        data-action
        data-button
        onClick={(event) => {
          action.onClick?.(event);

          if (!event.defaultPrevented) {
            deleteToast();
          }
        }}
        style={toast.actionButtonStyle || actionButtonStyle}
        type="button"
      >
        {action.label}
      </button>
    );
  })();

  const closeControl =
    showsCloseButton && !toast.jsx && toastType !== "loading" ? (
      <button
        aria-label={closeButtonAriaLabel}
        className={cn(classNames?.closeButton, toast.classNames?.closeButton)}
        data-ck-close-button
        data-disabled={isLoading}
        onClick={() => {
          if (isLoading || !dismissible) {
            return;
          }

          deleteToast();
          toast.onDismiss?.(toast);
        }}
        type="button"
      >
        {icons?.close ?? CloseGlyph}
      </button>
    ) : null;

  return (
    // The li is focusable and handles pointer swipes; keyboard dismissal
    // goes through the close or action buttons inside it.
    // oxlint-disable-next-line jsx-a11y/no-noninteractive-element-interactions, jsx-a11y/no-noninteractive-tabindex
    <li
      className={cn(
        styles.toast,
        className,
        toast.className,
        classNames?.toast,
        toast.classNames?.toast,
        classNames?.default,
        typeClassName,
        toastTypeClassName
      )}
      data-dismissible={dismissible}
      data-expanded={Boolean(expanded || (expandByDefault && mounted))}
      data-front={isFront}
      data-index={index}
      data-invert={inverted}
      data-mounted={mounted}
      data-promise={Boolean(toast.promise)}
      data-removed={removed}
      data-ck-rich-colors={toast.richColors ?? defaultRichColors}
      data-sonner-toast=""
      data-styled={!(toast.jsx || toast.unstyled || unstyled)}
      data-ck-swipe-direction={swipeOutDirection}
      data-ck-swipe-out={swipeOut}
      data-swiped={isSwiped}
      data-swiping={swiping}
      data-testid={toast.testId}
      data-type={toastType}
      data-visible={isVisible}
      data-ck-x-position={xPosition}
      data-ck-y-position={yPosition}
      onDragEnd={() => {
        setSwiping(false);
        setSwipeDirection(null);
        pointerStart.current = null;
      }}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      ref={toastRef}
      style={liStyle}
      tabIndex={0}
    >
      {closeControl}
      {toastIconSlot(toast, icons, classNames)}
      <div
        className={cn(classNames?.content, toast.classNames?.content)}
        data-content=""
      >
        <div
          className={cn(classNames?.title, toast.classNames?.title)}
          data-title=""
        >
          {toast.jsx || resolveContent(toast.title)}
        </div>
        {toast.description ? (
          <div
            className={cn(
              descriptionClassName,
              toast.descriptionClassName,
              classNames?.description,
              toast.classNames?.description
            )}
            data-description=""
          >
            {resolveContent(toast.description)}
          </div>
        ) : null}
      </div>
      {cancelButton}
      {actionButton}
    </li>
  );
};

export interface SonnerToasterProps {
  className?: string;
  closeButton?: boolean;
  containerAriaLabel?: string;
  dir?: "auto" | "ltr" | "rtl";
  duration?: number;
  expand?: boolean;
  gap?: number;
  hotkey?: readonly string[];
  icons?: ToastIcons;
  id?: string;
  invert?: boolean;
  mobileOffset?: ToastOffset;
  offset?: ToastOffset;
  position?: ToastPosition;
  ref?: Ref<HTMLElement>;
  richColors?: boolean;
  style?: CSSProperties;
  swipeDirections?: SwipeDirection[];
  theme?: "dark" | "light" | "system";
  toastOptions?: {
    actionButtonStyle?: CSSProperties;
    cancelButtonStyle?: CSSProperties;
    className?: string;
    classNames?: ToastClassNames;
    closeButton?: boolean;
    closeButtonAriaLabel?: string;
    descriptionClassName?: string;
    duration?: number;
    style?: CSSProperties;
    unstyled?: boolean;
  };
  visibleToasts?: number;
}

const DARK_QUERY = "(prefers-color-scheme: dark)";

/* The system colour scheme, read and followed like the theme=system. */
const systemTheme = (): "dark" | "light" =>
  window.matchMedia(DARK_QUERY).matches ? "dark" : "light";

const lightTheme = (): "dark" | "light" => "light";

const subscribeSystemTheme = (onChange: () => void) => {
  const query = window.matchMedia(DARK_QUERY);
  query.addEventListener("change", onChange);

  return () => {
    query.removeEventListener("change", onChange);
  };
};

const upsertToast = (current: ToastData[], event: ToastData) => {
  const index = current.findIndex((toast) => toast.id === event.id);

  if (index === -1) {
    return [event, ...current];
  }

  return [
    ...current.slice(0, index),
    { ...current[index], ...event },
    ...current.slice(index + 1),
  ];
};

const eventHasKey = (event: KeyboardEvent, key: string) =>
  Boolean((event as unknown as Record<string, unknown>)[key]) ||
  event.code === key;

export const SonnerToaster = ({
  id,
  invert,
  position = "bottom-right",
  hotkey = DEFAULT_HOTKEY,
  expand,
  closeButton,
  className,
  offset,
  mobileOffset,
  theme = "light",
  richColors,
  duration,
  style,
  visibleToasts = VISIBLE_TOASTS,
  toastOptions,
  dir = documentDirection(),
  gap = DEFAULT_GAP,
  icons,
  containerAriaLabel = DEFAULT_ARIA_LABEL,
  swipeDirections,
  ref,
}: SonnerToasterProps) => {
  const [allToasts, setAllToasts] = useState<ToastData[]>([]);

  const toasts = useMemo(
    () =>
      id
        ? allToasts.filter((toast) => toast.toasterId === id)
        : allToasts.filter((toast) => !toast.toasterId),
    [allToasts, id]
  );

  const positions = useMemo(
    () => [
      ...new Set([
        position,
        ...toasts.flatMap((toast) => (toast.position ? [toast.position] : [])),
      ]),
    ],
    [toasts, position]
  );

  const [heights, setHeights] = useState<ToastHeight[]>([]);
  const [expanded, setExpanded] = useState(false);
  const [interacting, setInteracting] = useState(false);

  const systemScheme = useSyncExternalStore(
    subscribeSystemTheme,
    systemTheme,
    lightTheme
  );

  const resolvedTheme = theme === "system" ? systemScheme : theme;

  const listRef = useRef<HTMLOListElement | null>(null);

  const hotkeyLabel = hotkey
    .join("+")
    .replaceAll(KEY_PREFIX, "")
    .replaceAll(DIGIT_PREFIX, "");

  const lastFocusedElement = useRef<HTMLElement | null>(null);
  const isFocusWithin = useRef(false);
  const [listMounted, setListMounted] = useState(false);

  const removeToast = useCallback((toast: ToastData) => {
    setAllToasts((current) => {
      if (!current.find((entry) => entry.id === toast.id)?.delete) {
        dismissToast(toast.id);
      }

      return current.filter(({ id: toastId }) => toastId !== toast.id);
    });
  }, []);

  useEffect(
    () =>
      subscribe((event) => {
        if (event.dismiss) {
          requestAnimationFrame(() => {
            setAllToasts((current) =>
              current.map((toast) =>
                toast.id === event.id ? { ...toast, delete: true } : toast
              )
            );
          });

          return;
        }

        setTimeout(() => {
          flushSync(() => {
            setAllToasts((current) => upsertToast(current, event));
          });
        }, 0);
      }),
    []
  );

  useEffect(() => {
    if (allToasts.length <= 1) {
      // oxlint-disable-next-line react/set-state-in-effect -- The component collapses the list when the toast state changes to one or none.
      setExpanded(false);
    }
  }, [allToasts]);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (hotkey.every((key) => eventHasKey(event, key))) {
        setExpanded(true);
        listRef.current?.focus();
      }

      if (
        event.code === "Escape" &&
        (document.activeElement === listRef.current ||
          listRef.current?.contains(document.activeElement))
      ) {
        setExpanded(false);
      }
    };

    document.addEventListener("keydown", onKeyDown);

    return () => {
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [hotkey]);

  useEffect(() => {
    if (listMounted) {
      return () => {
        if (lastFocusedElement.current) {
          lastFocusedElement.current.focus({ preventScroll: true });
          lastFocusedElement.current = null;
          isFocusWithin.current = false;
        }
      };
    }
  }, [listMounted]);

  const setList = useCallback((element: HTMLOListElement | null) => {
    listRef.current = element;
    setListMounted(element !== null);

    return () => {
      listRef.current = null;
      setListMounted(false);
    };
  }, []);

  return (
    <section
      aria-atomic="false"
      aria-label={`${containerAriaLabel} ${hotkeyLabel}`}
      aria-live="polite"
      aria-relevant="additions text"
      ref={ref}
      suppressHydrationWarning
      tabIndex={-1}
    >
      {positions.map((listPosition, positionIndex) => {
        const [yPosition, xPosition] = listPosition.split("-");

        if (!toasts.length) {
          return null;
        }

        return (
          <ol
            className={cn(styles.toaster, className)}
            data-sonner-theme={resolvedTheme}
            data-sonner-toaster
            data-ck-x-position={xPosition}
            data-ck-y-position={yPosition}
            dir={dir === "auto" ? documentDirection() : dir}
            key={listPosition}
            onBlur={(event) => {
              if (
                isFocusWithin.current &&
                !event.currentTarget.contains(event.relatedTarget)
              ) {
                isFocusWithin.current = false;

                if (lastFocusedElement.current) {
                  lastFocusedElement.current.focus({ preventScroll: true });
                  lastFocusedElement.current = null;
                }
              }
            }}
            onDragEnd={() => {
              setExpanded(false);
            }}
            onFocus={(event) => {
              if (
                (event.target instanceof HTMLElement &&
                  event.target.dataset.dismissible === "false") ||
                isFocusWithin.current
              ) {
                return;
              }

              isFocusWithin.current = true;
              lastFocusedElement.current =
                event.relatedTarget instanceof HTMLElement
                  ? event.relatedTarget
                  : null;
            }}
            onMouseEnter={() => {
              setExpanded(true);
            }}
            onMouseLeave={() => {
              if (!interacting) {
                setExpanded(false);
              }
            }}
            onMouseMove={() => {
              setExpanded(true);
            }}
            onPointerDown={(event) => {
              if (
                event.target instanceof HTMLElement &&
                event.target.dataset.dismissible === "false"
              ) {
                return;
              }

              setInteracting(true);
            }}
            onPointerUp={() => {
              setInteracting(false);
            }}
            ref={setList}
            style={
              {
                "--front-toast-height": `${heights[0]?.height || 0}px`,
                "--gap": `${gap}px`,
                "--width": `${TOAST_WIDTH}px`,
                ...style,
                ...offsetVariables(offset, mobileOffset),
              } as CSSProperties
            }
            tabIndex={-1}
          >
            {toasts
              .filter(
                (toast) =>
                  (!toast.position && positionIndex === 0) ||
                  toast.position === listPosition
              )
              .map((toast, index) => (
                <SonnerToast
                  actionButtonStyle={toastOptions?.actionButtonStyle}
                  cancelButtonStyle={toastOptions?.cancelButtonStyle}
                  className={toastOptions?.className}
                  classNames={toastOptions?.classNames}
                  closeButton={toastOptions?.closeButton ?? closeButton}
                  closeButtonAriaLabel={toastOptions?.closeButtonAriaLabel}
                  defaultRichColors={richColors}
                  descriptionClassName={toastOptions?.descriptionClassName}
                  duration={toastOptions?.duration ?? duration}
                  expandByDefault={expand}
                  expanded={expanded}
                  gap={gap}
                  heights={heights.filter(
                    (height) => height.position === toast.position
                  )}
                  icons={icons}
                  index={index}
                  interacting={interacting}
                  invert={invert}
                  key={toast.id}
                  position={listPosition}
                  removeToast={removeToast}
                  setHeights={setHeights}
                  style={toastOptions?.style}
                  swipeDirections={swipeDirections}
                  toast={toast}
                  toasts={toasts.filter(
                    (entry) => entry.position === toast.position
                  )}
                  unstyled={toastOptions?.unstyled}
                  visibleToasts={visibleToasts}
                />
              ))}
          </ol>
        );
      })}
    </section>
  );
};

/*
 * Toast stack rules based on the Sonner stylesheet, with the app overrides
 * (.sheet-toaster). Tailwind cannot define @keyframes or match Sonner's
 * data attributes with a single rule, so the stack rules sit here. Selector
 * specificity follows Sonner:
 * [data-sonner-toaster] is .toaster, [data-sonner-toast] is .toast,
 * [data-sonner-toaster].sheet-toaster is .toaster.viewport.
 */

.toaster {
  position: fixed;
  width: var(--width);
  font-family:
    ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
    "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
  box-sizing: border-box;
  padding: 0;
  margin: 0;
  list-style: none;
  outline: 0;
  z-index: 999999999;
  transition: transform 0.4s ease;
}

.toaster[dir="ltr"] {
  --toast-close-button-start: 0;
  --toast-close-button-end: unset;
}

.toaster[dir="rtl"] {
  --toast-close-button-start: unset;
  --toast-close-button-end: 0;
}

@media (hover: none) and (pointer: coarse) {
  .toaster[data-lifted="true"] {
    transform: none;
  }
}

.toaster[data-ck-x-position="right"] {
  right: var(--offset-right);
}

.toaster[data-ck-x-position="left"] {
  left: var(--offset-left);
}

.toaster[data-ck-x-position="center"] {
  left: 50%;
  transform: translateX(-50%);
}

.toaster[data-ck-y-position="top"] {
  top: var(--offset-top);
}

.toaster[data-ck-y-position="bottom"] {
  bottom: var(--offset-bottom);
}

@media (max-width: 600px) {
  .toaster {
    position: fixed;
    right: var(--mobile-offset-right);
    left: var(--mobile-offset-left);
    width: 100%;
  }

  .toaster[dir="rtl"] {
    left: calc(var(--mobile-offset-left) * -1);
  }

  .toaster .toast {
    left: 0;
    right: 0;
    width: calc(100% - var(--mobile-offset-left) * 2);
  }

  .toaster[data-ck-x-position="left"] {
    left: var(--mobile-offset-left);
  }

  .toaster[data-ck-y-position="bottom"] {
    bottom: var(--mobile-offset-bottom);
  }

  .toaster[data-ck-y-position="top"] {
    top: var(--mobile-offset-top);
  }

  .toaster[data-ck-x-position="center"] {
    left: var(--mobile-offset-left);
    right: var(--mobile-offset-right);
    transform: none;
  }
}

/* App overrides: .sheet-toaster. */
.toaster.viewport {
  width: 100%;
  transition-duration: var(--motion-duration-slow);
  font-family: inherit;
  position: absolute;
  top: 0;
}

.toaster.viewport[data-ck-x-position="right"] {
  inset-inline: calc(var(--spacing, 0.25rem) * 6);
  top: calc(var(--spacing, 0.25rem) * 14);
  width: auto;
  max-width: calc(var(--spacing, 0.25rem) * 80);
  margin-inline-start: auto;
  position: fixed;
}

.toaster.viewport .toast,
.toaster.viewport .toast > * {
  transition-duration: var(--motion-duration-slow);
}

.toast {
  --y: translateY(100%);
  --lift-amount: calc(var(--lift) * var(--gap));
  z-index: var(--z-index);
  position: absolute;
  opacity: 0;
  transform: var(--y);
  touch-action: none;
  transition:
    transform 0.4s,
    opacity 0.4s,
    height 0.4s,
    box-shadow 0.2s;
  box-sizing: border-box;
  outline: 0;
  overflow-wrap: anywhere;
}

.toast:focus-visible {
  box-shadow: var(--shadow-toast), var(--shadow-toast-ring);
}

.toast[data-ck-y-position="top"] {
  top: 0;
  --y: translateY(-100%);
  --lift: 1;
  --lift-amount: calc(1 * var(--gap));
}

.toast[data-ck-y-position="bottom"] {
  bottom: 0;
  --y: translateY(100%);
  --lift: -1;
  --lift-amount: calc(var(--lift) * var(--gap));
}

.toast[data-swiping="true"]::before {
  content: "";
  position: absolute;
  left: -100%;
  right: -100%;
  height: 100%;
  z-index: -1;
}

.toast[data-ck-y-position="top"][data-swiping="true"]::before {
  bottom: 50%;
  transform: scaleY(3) translateY(50%);
}

.toast[data-ck-y-position="bottom"][data-swiping="true"]::before {
  top: 50%;
  transform: scaleY(3) translateY(-50%);
}

.toast[data-swiping="false"][data-removed="true"]::before {
  content: "";
  position: absolute;
  inset: 0;
  transform: scaleY(2);
}

.toast[data-expanded="true"]::after {
  content: "";
  position: absolute;
  left: 0;
  height: calc(var(--gap) + 1px);
  bottom: 100%;
  width: 100%;
}

.toast[data-mounted="true"] {
  --y: translateY(0);
  opacity: 1;
}

.toast[data-expanded="false"][data-front="false"] {
  --scale: var(--toasts-before) * 0.05 + 1;
  --y: translateY(calc(var(--lift-amount) * var(--toasts-before)))
    scale(calc(-1 * var(--scale)));
  height: var(--front-toast-height);
}

.toast > * {
  transition: opacity 0.4s;
}

.toast[data-ck-x-position="right"] {
  right: 0;
}

.toast[data-ck-x-position="left"] {
  left: 0;
}

.toast[data-visible="false"] {
  opacity: 0;
  pointer-events: none;
}

.toast[data-mounted="true"][data-expanded="true"] {
  --y: translateY(calc(var(--lift) * var(--offset)));
  height: var(--initial-height);
}

.toast[data-removed="true"][data-front="true"][data-ck-swipe-out="false"] {
  --y: translateY(calc(var(--lift) * -100%));
  opacity: 0;
}

.toast[data-removed="true"][data-front="false"][data-ck-swipe-out="false"][data-expanded="true"] {
  --y: translateY(calc(var(--lift) * var(--offset) + var(--lift) * -100%));
  opacity: 0;
}

.toast[data-removed="true"][data-front="false"][data-ck-swipe-out="false"][data-expanded="false"] {
  --y: translateY(40%);
  opacity: 0;
  transition:
    transform 0.5s,
    opacity 0.2s;
}

.toast[data-removed="true"][data-front="false"]::before {
  height: calc(var(--initial-height) + 20%);
}

.toast[data-swiping="true"] {
  transform: var(--y) translateY(var(--swipe-amount-y, 0))
    translateX(var(--swipe-amount-x, 0));
  transition: none;
}

.toast[data-swiped="true"] {
  user-select: none;
}

.toast[data-ck-swipe-out="true"][data-ck-y-position="bottom"],
.toast[data-ck-swipe-out="true"][data-ck-y-position="top"] {
  animation-duration: 0.2s;
  animation-timing-function: ease-out;
  animation-fill-mode: forwards;
}

.toast[data-ck-swipe-out="true"][data-ck-swipe-direction="left"] {
  animation-name: swipe-out-left;
}

.toast[data-ck-swipe-out="true"][data-ck-swipe-direction="right"] {
  animation-name: swipe-out-right;
}

.toast[data-ck-swipe-out="true"][data-ck-swipe-direction="up"] {
  animation-name: swipe-out-up;
}

.toast[data-ck-swipe-out="true"][data-ck-swipe-direction="down"] {
  animation-name: swipe-out-down;
}

@keyframes swipe-out-left {
  from {
    transform: var(--y) translateX(var(--swipe-amount-x));
    opacity: 1;
  }

  to {
    transform: var(--y) translateX(calc(var(--swipe-amount-x) - 100%));
    opacity: 0;
  }
}

@keyframes swipe-out-right {
  from {
    transform: var(--y) translateX(var(--swipe-amount-x));
    opacity: 1;
  }

  to {
    transform: var(--y) translateX(calc(var(--swipe-amount-x) + 100%));
    opacity: 0;
  }
}

@keyframes swipe-out-up {
  from {
    transform: var(--y) translateY(var(--swipe-amount-y));
    opacity: 1;
  }

  to {
    transform: var(--y) translateY(calc(var(--swipe-amount-y) - 100%));
    opacity: 0;
  }
}

@keyframes swipe-out-down {
  from {
    transform: var(--y) translateY(var(--swipe-amount-y));
    opacity: 1;
  }

  to {
    transform: var(--y) translateY(calc(var(--swipe-amount-y) + 100%));
    opacity: 0;
  }
}

@media (prefers-reduced-motion) {
  .toast,
  .toast > * {
    transition: none !important;
    animation: none !important;
  }
}

.appToast {
  pointer-events: auto;
  width: max-content;
  max-width: 100%;
}

.contents {
  display: contents;
}

.appToast.contentCentered {
  max-width: min(100%, var(--toast-body-max-width, 100%));
  translate: var(--toast-body-offset-x, 0px);
}

/*
 * Styled-mode rules of the vendored Sonner stylesheet (data-styled=true,
 * data-ck-rich-colors, themes, buttons, close button, loader). The app mounts
 * every toast unstyled, so these only apply to toasts made with the vendored
 * helpers (success, info, warning, error, loading, promise, message).
 */

.toaster {
  --gray1: hsl(0, 0%, 99%);
  --gray2: hsl(0, 0%, 97.3%);
  --gray3: hsl(0, 0%, 95.1%);
  --gray4: hsl(0, 0%, 93%);
  --gray5: hsl(0, 0%, 90.9%);
  --gray6: hsl(0, 0%, 88.7%);
  --gray7: hsl(0, 0%, 85.8%);
  --gray8: hsl(0, 0%, 78%);
  --gray9: hsl(0, 0%, 56.1%);
  --gray10: hsl(0, 0%, 52.3%);
  --gray11: hsl(0, 0%, 43.5%);
  --gray12: hsl(0, 0%, 9%);
  --border-radius: 8px;
}

.toaster[dir="ltr"] {
  --toast-icon-margin-start: -3px;
  --toast-icon-margin-end: 4px;
  --toast-svg-margin-start: -1px;
  --toast-svg-margin-end: 0px;
  --toast-button-margin-start: auto;
  --toast-button-margin-end: 0;
  --toast-close-button-transform: translate(-35%, -35%);
}

.toaster[dir="rtl"] {
  --toast-icon-margin-start: 4px;
  --toast-icon-margin-end: -3px;
  --toast-svg-margin-start: 0px;
  --toast-svg-margin-end: -1px;
  --toast-button-margin-start: 0;
  --toast-button-margin-end: auto;
  --toast-close-button-transform: translate(35%, -35%);
}

.toast[data-styled="true"] {
  padding: 16px;
  background: var(--normal-bg);
  border: 1px solid var(--normal-border);
  color: var(--normal-text);
  border-radius: var(--border-radius);
  box-shadow: var(--shadow-toast);
  width: var(--width);
  font-size: 13px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.toast[data-styled="true"] [data-description] {
  font-weight: 400;
  line-height: 1.4;
  color: var(--ck-palette-ink-secondary);
}

.toast[data-ck-rich-colors="true"][data-styled="true"] [data-description] {
  color: inherit;
}

.toaster[data-sonner-theme="dark"] [data-description] {
  color: var(--ck-palette-ink-secondary);
}

.toast[data-styled="true"] [data-title] {
  font-weight: 500;
  line-height: 1.5;
  color: inherit;
}

.toast[data-styled="true"] [data-icon] {
  display: flex;
  height: 16px;
  width: 16px;
  position: relative;
  justify-content: flex-start;
  align-items: center;
  flex-shrink: 0;
  margin-left: var(--toast-icon-margin-start);
  margin-right: var(--toast-icon-margin-end);
}

.toast[data-promise="true"] [data-icon] > svg {
  opacity: 0;
  transform: scale(0.8);
  transform-origin: center;
  animation: sonner-fade-in 0.3s ease forwards;
}

.toast[data-styled="true"] [data-icon] > * {
  flex-shrink: 0;
}

.toast[data-styled="true"] [data-icon] svg {
  margin-left: var(--toast-svg-margin-start);
  margin-right: var(--toast-svg-margin-end);
}

.toast[data-styled="true"] [data-content] {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.toast[data-styled="true"] [data-button] {
  border-radius: 4px;
  padding-left: 8px;
  padding-right: 8px;
  height: 24px;
  font-size: 12px;
  color: var(--normal-bg);
  background: var(--normal-text);
  margin-left: var(--toast-button-margin-start);
  margin-right: var(--toast-button-margin-end);
  border: none;
  font-weight: 500;
  cursor: pointer;
  outline: 0;
  display: flex;
  align-items: center;
  flex-shrink: 0;
  transition:
    opacity 0.4s,
    box-shadow 0.2s;
}

.toast[data-styled="true"] [data-button]:focus-visible {
  box-shadow: var(--shadow-focus-ring);
}

.toast[data-styled="true"] [data-button]:first-of-type {
  margin-left: var(--toast-button-margin-start);
  margin-right: var(--toast-button-margin-end);
}

.toast[data-styled="true"] [data-cancel] {
  color: var(--normal-text);
  background: color-mix(in srgb, var(--ck-fixed-black) 8%, transparent);
}

.toaster[data-sonner-theme="dark"] .toast[data-styled="true"] [data-cancel] {
  background: color-mix(in srgb, var(--ck-fixed-white) 30%, transparent);
}

.toast[data-styled="true"] [data-ck-close-button] {
  position: absolute;
  left: var(--toast-close-button-start);
  right: var(--toast-close-button-end);
  top: 0;
  height: 20px;
  width: 20px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 0;
  color: var(--gray12);
  background: var(--normal-bg);
  border: 1px solid var(--gray4);
  transform: var(--toast-close-button-transform);
  border-radius: 50%;
  cursor: pointer;
  z-index: 1;
  transition:
    opacity 0.1s,
    background 0.2s,
    border-color 0.2s;
}

.toast[data-styled="true"] [data-ck-close-button]:focus-visible {
  box-shadow: var(--shadow-toast), var(--shadow-toast-ring);
}

.toast[data-styled="true"] [data-disabled="true"] {
  cursor: not-allowed;
}

.toast[data-styled="true"]:hover [data-ck-close-button]:hover {
  background: var(--gray2);
  border-color: var(--gray5);
}

.toast[data-expanded="false"][data-front="false"][data-styled="true"] > * {
  opacity: 0;
}

.toaster[data-sonner-theme="light"] {
  --normal-bg: var(--ck-palette-surface-surface);
  --normal-border: var(--gray4);
  --normal-text: var(--gray12);
  --success-bg: hsl(143, 85%, 96%);
  --success-border: hsl(145, 92%, 87%);
  --success-text: hsl(140, 100%, 27%);
  --info-bg: hsl(208, 100%, 97%);
  --info-border: hsl(221, 91%, 93%);
  --info-text: hsl(210, 92%, 45%);
  --warning-bg: hsl(49, 100%, 97%);
  --warning-border: hsl(49, 91%, 84%);
  --warning-text: hsl(31, 92%, 45%);
  --error-bg: hsl(359, 100%, 97%);
  --error-border: hsl(359, 100%, 94%);
  --error-text: hsl(360, 100%, 45%);
}

.toaster[data-sonner-theme="light"] .toast[data-invert="true"] {
  --normal-bg: var(--ck-palette-surface-surface);
  --normal-border: hsl(0, 0%, 20%);
  --normal-text: var(--gray1);
}

.toaster[data-sonner-theme="dark"] .toast[data-invert="true"] {
  --normal-bg: var(--ck-palette-surface-surface);
  --normal-border: var(--gray3);
  --normal-text: var(--gray12);
}

.toaster[data-sonner-theme="dark"] {
  --normal-bg: var(--ck-palette-surface-surface);
  --normal-bg-hover: hsl(0, 0%, 12%);
  --normal-border: hsl(0, 0%, 20%);
  --normal-border-hover: hsl(0, 0%, 25%);
  --normal-text: var(--gray1);
  --success-bg: hsl(150, 100%, 6%);
  --success-border: hsl(147, 100%, 12%);
  --success-text: hsl(150, 86%, 65%);
  --info-bg: hsl(215, 100%, 6%);
  --info-border: hsl(223, 43%, 17%);
  --info-text: hsl(216, 87%, 65%);
  --warning-bg: hsl(64, 100%, 6%);
  --warning-border: hsl(60, 100%, 9%);
  --warning-text: hsl(46, 87%, 65%);
  --error-bg: hsl(358, 76%, 10%);
  --error-border: hsl(357, 89%, 16%);
  --error-text: hsl(358, 100%, 81%);
}

.toaster[data-sonner-theme="dark"] .toast [data-ck-close-button] {
  background: var(--normal-bg);
  border-color: var(--normal-border);
  color: var(--normal-text);
}

.toaster[data-sonner-theme="dark"] .toast [data-ck-close-button]:hover {
  background: var(--normal-bg-hover);
  border-color: var(--normal-border-hover);
}

.toast[data-ck-rich-colors="true"][data-type="success"] {
  background: var(--success-bg);
  border-color: var(--success-border);
  color: var(--success-text);
}

.toast[data-ck-rich-colors="true"][data-type="success"] [data-ck-close-button] {
  background: var(--success-bg);
  border-color: var(--success-border);
  color: var(--success-text);
}

.toast[data-ck-rich-colors="true"][data-type="info"] {
  background: var(--info-bg);
  border-color: var(--info-border);
  color: var(--info-text);
}

.toast[data-ck-rich-colors="true"][data-type="info"] [data-ck-close-button] {
  background: var(--info-bg);
  border-color: var(--info-border);
  color: var(--info-text);
}

.toast[data-ck-rich-colors="true"][data-type="warning"] {
  background: var(--warning-bg);
  border-color: var(--warning-border);
  color: var(--warning-text);
}

.toast[data-ck-rich-colors="true"][data-type="warning"] [data-ck-close-button] {
  background: var(--warning-bg);
  border-color: var(--warning-border);
  color: var(--warning-text);
}

.toast[data-ck-rich-colors="true"][data-type="error"] {
  background: var(--error-bg);
  border-color: var(--error-border);
  color: var(--error-text);
}

.toast[data-ck-rich-colors="true"][data-type="error"] [data-ck-close-button] {
  background: var(--error-bg);
  border-color: var(--error-border);
  color: var(--error-text);
}

.loadingWrapper {
  --size: 16px;
  height: var(--size);
  width: var(--size);
  position: absolute;
  inset: 0;
  z-index: 10;
}

.loadingWrapper[data-visible="false"] {
  transform-origin: center;
  animation: sonner-fade-out 0.2s ease forwards;
}

.spinner {
  position: relative;
  top: 50%;
  left: 50%;
  height: var(--size);
  width: var(--size);
}

.loadingBar {
  animation: sonner-spin 1.2s linear infinite;
  background: var(--gray11);
  border-radius: 6px;
  height: 8%;
  left: -10%;
  position: absolute;
  top: -3.9%;
  width: 24%;
}

.loadingBar:first-child {
  animation-delay: -1.2s;
  transform: rotate(0.0001deg) translate(146%);
